__NUXT_JSONP__("/it/how-to-apply/short", (function(a){return {data:[{details:{slug:"it",pageTitle:"Application Process for Short-term Overseas | Mentor Language Institute",pageDescription:a,title:"Application Process for Short-term Overseas",image:"\u002Fimages\u002Fshort\u002Fpassport-jp.jpg",category:[{title:"Less than 90 days",content:[a,"-A person living outside of the U.S.\u003Cbr \u002F\u003E-A person planning to stay in the U.S. less than 90 days."]},{title:"Application Steps",image:"\u002Fimages\u002Fshort\u002Fmli-design-apply-short-en.jpg",ordered_content:["Apply to MLI","Submit the documents","Recieve the final confirmation","Leave for the U.S."],content:["Short-term international students do not need a visa. However it is recommended that you complete the application process as early as possible to secure housing and class registration.","MLI is especially busy during summer holidays and spring breaks. Therefore, even for short-term study,\u003Cb\u003Ewe recommend you complete the application at least two months prior to departure.\u003C\u002Fb\u003E"],types:[{title:"Cancellation Policy",content:["The enrollment fee of $150, will be charged at the time of application. The enrollment fee is non-refundable regardless if an application is rejected or enrollment is cancelled. Exceptions include insufficient housing."]}]},{title:"About the steps after application",image:"\u002Fimages\u002Fshort\u002Fmli-short-en.jpg",content:["After students have applied, the iMLI system processes the application. Students can follow the process which is listed on the iMLI."],types:[{title:"Apply Online",content:["Fill out the information about your visa status \u003Cbr \u002F\u003E Contact us via iMLI for all inquiries","Apply from below."]}]}],btn_label:"Online Application Form",admission:{link:"\u002Fit\u002Fadmission",content:["*Please have your credit card in hand."]},dir:"\u002Fshort",path:"\u002Fshort\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:31.067Z",updatedAt:"2025-05-26T12:06:27.916Z"}}],fetch:{},mutations:void 0}}("Who is elgible to apply for short-term study?")));